  <div class="mvu-status-card"><div class="card-body" id="render-root"><div class="loading-state">正在加载状态数据...</div></div></div>
  <script type="module">
    /* 兜底模板：自动遍历 stat_data 所有键值对动态渲染，无需硬编码字段名 */
    /* 路径根为 stat_data 内部，从一级分类开始（不写 stat_data. 前缀） */
    function renderValue(val) {
      if (val === null || val === undefined) return '<span class="value-text">-</span>';
      if (typeof val === 'boolean') { var cls = val ? 'value-true' : 'value-false'; var txt = val ? '是' : '否'; return '<span class="'+cls+'">'+txt+'</span>'; }
      if (typeof val === 'number') return '<span class="value-number">'+val+'</span>';
      if (typeof val === 'string') return '<span class="value-text">'+val+'</span>';
      if (Array.isArray(val)) return '<span class="value-text">'+val.length+' 项</span>';
      return '<span class="value-text">'+Object.keys(val).length+' 项</span>';
    }
    function isNumberLike(v) { return typeof v === 'number' && v >= 0 && v <= 100; }
    function renderCategory(name, obj) {
      var keys = Object.keys(obj);
      var items = keys.map(function(k) {
        var v = obj[k];
        if (v && typeof v === 'object' && !Array.isArray(v)) {
          return '<div class="stat-item"><span class="stat-label">'+k+'</span>'+renderValue(v)+'</div>';
        }
        var valHtml = renderValue(v);
        var barHtml = isNumberLike(v) ? '<div class="progress-bar"><div class="progress-bar-fill" style="width:'+v+'%"></div></div>' : '';
        return '<div class="stat-item"><span class="stat-label">'+k+'</span>'+valHtml+barHtml+'</div>';
      }).join('');
      return '<div class="category-title">'+name+'</div><div class="stat-grid">'+items+'</div>';
    }
    function populateCharacterData() {
      try {
        var all_variables = getAllVariables();
        var data = _.get(all_variables, 'stat_data', {});
        var root = document.getElementById('render-root');
        if (!root) return;
        if (!data || typeof data !== 'object' || Object.keys(data).length === 0) {
          root.innerHTML = '<div class="loading-state">暂无变量数据</div>';
          return;
        }
        var html = Object.keys(data).map(function(cat) {
          var v = data[cat];
          if (v && typeof v === 'object' && !Array.isArray(v)) {
            return renderCategory(cat, v);
          }
          return '<div class="stat-item"><span class="stat-label">'+cat+'</span>'+renderValue(v)+'</div>';
        }).join('');
        root.innerHTML = html;
        root.classList.add('flash-update');
        setTimeout(function() { root.classList.remove('flash-update'); }, 300);
      } catch (e) {
        console.warn('[statusbar] populateCharacterData 失败:', e.message);
      }
    }

    async function init() {
      await waitGlobalInitialized('Mvu');
      populateCharacterData();
      /* 用户模板标准：eventOn(Mvu.events.VARIABLE_UPDATE_ENDED) 事件驱动刷新，禁止setInterval轮询 */
      try { if (typeof Mvu !== 'undefined' && Mvu.events) eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, populateCharacterData); } catch(e) {}
    }

    $(errorCatched(init));
  </script>
</body>
</html>
