import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

export const Schema = z.object({
  identity: z.object({
    exposure_risk: z.coerce.number().prefault(0),
    disguise_rank: z.string().prefault('完美优等生'),
    item_status: z.string().prefault('正常穿戴')
  }).prefault({ exposure_risk: 0, disguise_rank: '完美优等生', item_status: '正常穿戴' }),
  social: z.object({
    haruko_bond: z.coerce.number().prefault(10),
    school_tier: z.string().prefault('外部考入者'),
    popularity: z.coerce.number().prefault(50)
  }).prefault({ haruko_bond: 10, school_tier: '外部考入者', popularity: 50 }),
  world: z.object({
    time_period: z.string().prefault('早课'),
    active_event: z.string().prefault('入社风波')
  }).prefault({ time_period: '早课', active_event: '入社风波' })
});

/* 结尾固定注册函数 */
$(() => { registerMvuSchema(Schema); })
